example_item.example_item_data:
% La page de synthese d'un enregistrement simule avec une salve ectopique, en PNG.
recording = ecglab.simulate('Seconds', 120, 'Ectopic', 0.1, 'Seed', 1);
handle = ecglab.chart(recording, 'OutputImage', [tempdir(), '/summary.png']);

% Analyser une fois, puis tracer la page depuis l'analyse pour ne pas analyser deux fois.
recording = ecglab.simulate('Seconds', 60, 'Rate', 500, 'Leads', 12, 'Seed', 2);
analysis = ecglab.analyze(recording);
ecglab.chart(analysis);
